# -*- coding: utf-8 -*-
"""Georgian headwords and definitions for the Glossary. TERMS = {id: (headword, definition)}."""
TERMS = {
"abbot": ("წინამძღვარი (იღუმენი)", "მონასტრის წინამძღვარი."),
"aer": ("აერი", "უდიდესი საბურველთაგან, რომელიც ერთად ფარავს დისკოსსა და ბარძიმს და რომლითაც ფრიალებენ ძღვენზე სარწმუნოების სიმბოლოს დროს."),
"toll-houses": ("საჰაერო საზვერეები", "თხრობა სულის სიკვდილის შემდგომი გზის შესახებ, სადაც მას დემონები ეტაპობრივად გამოსცდიან. გვხვდება მამათა, აგიოგრაფიულ და საღვთისმსახურო წყაროებში და მას ასწავლის მრავალი წმინდანი."),
"akathist": ("აკათისტო", "ოცდაოთხსტროფიანი საგალობელი, რომელიც იგალობება ფეხზე მდგომთ, რაზეც თვით სახელიც მიუთითებს. პირველი ღვთისმშობლისაა; მრავალი გვიანდელი მის ფორმას მისდევს."),
"akriveia": ("აკრივია", "სიზუსტე: კანონთა მკაცრი გამოყენება, იკონომიის შესატყვისი."),
"vigil": ("სრულღამისთევა", "მწუხრი, ცისკარი და პირველი ჟამი შეერთებული ერთ მსახურებად კვირისა და დიდ დღესასწაულთა წინა საღამოს."),
"alleluiarion": ("ალილუარი", "ალილუია თავისი მუხლებით, რომელიც იგალობება სამოციქულოსა და სახარებას შორის."),
"ambo": ("ამბიონი", "სოლეას წინამდებარე შვერილი სამეუფო კარის წინ, საიდანაც იკითხება სახარება და წარმოითქმის ამბიონსგარეთა ლოცვა."),
"analavos": ("ანალავი", "დიდი სქემის შესამოსელი, ნაქარგი ჯვრით, ლახვრით, ღრუბლითა და ვნებათა სიტყვებით."),
"analogion": ("კანკელი (ანალოღიონი)", "დახრილი დგამი, რომელზეც დევს ხატი ან საღვთისმსახურო წიგნი."),
"anaphora": ("ანაფორა", "ჟამისწირვის ცენტრალური ლოცვა, შეწირვა, რომელიც შეიცავს დამდებ სიტყვებსა და ეპიკლეზას."),
"antidoron": ("ანტიდორი", "პროსფორის ნარჩენი, კურთხეული მაგრამ არა განწმედილი, რომელიც ურიგდება ჟამისწირვის ბოლოს. სახელი ნიშნავს ძღვნის ნაცვლად: მიეცემა ყველა დამსწრეს, მათაც, ვინც არ ეზიარა."),
"antimension": ("ანტიმინსი", "ეპისკოპოსის მიერ ხელმოწერილი ქსოვილი, რომელიც შეიცავს ნაწილებს და იშლება საკურთხევლის ტრაპეზზე. მის გარეშე ჟამისწირვა არ აღესრულება: ეს არის ეპისკოპოსის ნებართვა ტრაპეზისთვის."),
"apatheia": ("უვნებობა (აპათია)", "არა უგრძნობლობა, არამედ ვნებათა განკურნება, რათა სულის ძალები სწორად მიიმართოს ღვთისკენ."),
"apostles-fast": ("მოციქულთა მარხვა", "მარხვა ყოველთა წმიდათა კვირის შემდგომი ორშაბათიდან წმიდა პეტრესა და პავლეს დღესასწაულამდე 29 ივნისს. მისი ხანგრძლივობა იცვლება აღდგომის თარიღის მიხედვით."),
"archbishop": ("მთავარეპისკოპოსი", "უფროსი ეპისკოპოსი. ბერძნულ პრაქტიკაში იგი ჩვეულებრივ მიტროპოლიტზე მაღლა დგას, სლავურში კი დაბლა."),
"archimandrite": ("არქიმანდრიტი", "უფროსი მღვდელმონაზონი, ხშირად მონასტრის წინამძღვარი ან საეპისკოპოსო კანდიდატი."),
"archpriest": ("დეკანოზი (მთავარხუცესი)", "უფროსი სამრევლო მღვდელი; ეს არის ჯილდო და არა ცალკე ხარისხი."),
"artoklasia": ("პურის კურთხევა (არტოკლასია)", "ხუთი პურის კურთხევა და გატეხა ლიტიაზე, ხუთი ათასის გამოზრდის მოსახსენებლად."),
"asterisk": ("ვარსკვლავი (ასტერისკი)", "დასაკეცი ვარსკვლავი, დადგმული დისკოსზე, რათა საბურველმა ნაწილაკებს არ შეეხოს; მოგვაგონებს ბეთლემის ვარსკვლავს."),
"autocephaly": ("ავტოკეფალია", "ეკლესიის მდგომარეობა, რომელიც თავად ირჩევს თავის წინამძღვარს და არ ექვემდებარება სხვას, დარჩენილი დანარჩენებთან ზიარებაში."),
"autonomy": ("ავტონომია", "ეკლესიის მდგომარეობა, რომელიც თავად იმართება, მაგრამ რომლის წინამძღვარსაც ამტკიცებს დედა-ეკლესია."),
"baptism": ("ნათლისღება", "სამგზისი შთაფლვა ქრისტეს სიკვდილსა და აღდგომაში, რითაც ადამიანი შემოდის ეკლესიაში."),
"odes": ("ბიბლიური გალობანი", "ცხრა ბიბლიური გალობა, მოსეს გალობებიდან ღვთისმშობლის საგალობლამდე და ზაქარიას ლოცვამდე, რომელთა მიხედვითაც იწერება კანონის გალობები."),
"bishop": ("ეპისკოპოსი", "სამი დიდი ხარისხიდან უმაღლესი, რომელსაც აქვს მღვდლობის სისრულე, ხელს ასხამს სასულიერო პირებს და არის თავისი ეპარქიის ერთობის ცენტრი."),
"bright-week": ("ბრწყინვალე შვიდეული", "აღდგომის შემდგომი შვიდეული, რომელიც ინახება როგორც დღესასწაულის ერთი განუწყვეტელი დღე, უმარხვოდ და ღია სამეუფო კარით."),
"canon-hymn": ("კანონი (საგალობელი)", "ცისკრის ვრცელი საგალობელი რვა ან ცხრა გალობად, თითოეული დაკავშირებული ერთ-ერთ ბიბლიურ გალობასთან."),
"canon-law": ("კანონი (წესი)", "ეკლესიის წესი, მიცემული კრებისა თუ მამის მიერ და მიღებული მთელი სხეულის მიერ. განსხვავდება ცისკარზე გალობილი კანონისგან."),
"catechumen": ("მოქათალე (კატეხუმენი)", "სარწმუნოებაში დამოძღვრილი ნათლისღებისთვის მოსამზადებლად; ძველი წესით გადის მორწმუნეთა ჟამისწირვამდე."),
"catholicity": ("კათოლიკობა (საკრებულოობა)", "ეკლესიის სისრულე: არა გავრცელება, არამედ სისავსე, ვინაიდან თითოეული ადგილობრივი ეკლესია, თავისი ეპისკოპოსის გარშემო შეკრებილი, ფლობს მთელს. გამოთქმა მთელის მიხედვით გადმოსცემს kath' holon-ს."),
"censer": ("საცეცხლური", "ჭურჭელი, რომელშიც იწვება საკმეველი; სლავურ და ბერძნულ ხმარებათა უმეტესობაში ზარაკებით."),
"chalice": ("ბარძიმი", "სასმისი, რომელიც შეიცავს შესაწირავ ღვინოს, ხოლო კურთხევის შემდეგ ქრისტეს სისხლს."),
"cherubic-hymn": ("ქერუბიმთა საგალობელი", "საგალობელი, რომელიც იგალობება დიდ შესვლაზე, როცა მორწმუნენი განიშორებენ ყოველ ამქვეყნიურ ზრუნვას, რათა მიიღონ ყოველთა მეუფე."),
"chrismation": ("მირონცხება", "წმიდა მირონით ცხება ნათლისღებისთანავე, სულიწმიდის ნიჭის ბეჭედი."),
"churching": ("ეკლესიაში შეყვანა", "დედისა და ჩვილის მოყვანა ტაძარში მეორმოცე დღეს, სამადლობელი და საკურთხეველი ლოცვებით."),
"clean-monday": ("სუფთა ორშაბათი", "დიდი მარხვის პირველი დღე, შენდობის კვირის შემდეგ."),
"spoon": ("კოვზი (ლაბისი)", "კოვზი, რომლითაც მორწმუნენი იღებენ ხორცსა და სისხლს ერთად. მისი ბერძნული სახელი ნიშნავს მარწუხს, ესაიას ხილვაში მარწუხით აღებული ნაკვერცხლის მიხედვით."),
"compline": ("ძილის წინა ლოცვა (აპოდიპნონი)", "მსახურება ვახშმის შემდეგ, ძილის წინ. მცირე გამოიყენება წლის უმეტეს ნაწილში; დიდი ეკუთვნის დიდ მარხვასა და ზოგიერთ ღამისთევას."),
"compunction": ("გულის შემუსვრილება (კატანიქსისი)", "გულის განგმირვა, რომელიც ცრემლს მოაქვს და მას ღვთისკენ არბილებს."),
"confession": ("აღსარება", "სინანულის საიდუმლო, რომელშიც ცოდვები აღიარებულია ღვთის წინაშე მღვდლის თანდასწრებით და მიეცემა შენდობა. მისი სიხშირე მკვეთრად განსხვავდება ტრადიციათა შორის."),
"crowning": ("ჯვრისწერა", "ქორწინების საიდუმლო, ასე წოდებული იმ გვირგვინთაგან, რომელნიც დაესხმის მექორწინეთა თავს და აღნიშნავს როგორც სამეფოს, ისე მოწამეობას."),
"deacon": ("დიაკვანი", "მესამე ხარისხი, რომელიც ემსახურება საკურთხეველს, წარმოთქვამს კვერექსებს და მარტო ვერ აღასრულებს საიდუმლოებს."),
"dikirion": ("დიკირი და ტრიკირი", "ორ და სამტოტიანი სასანთლეები, რომლითაც ეპისკოპოსი აკურთხებს, აღმნიშვნელი ქრისტეს ორი ბუნებისა და სამების სამი პირისა."),
"diptychs": ("დიპტიქონები", "ცოცხალთა და გარდაცვლილთა სიები, რომელნიც მოიხსენიებიან ჟამისწირვაზე, ხოლო წინამძღვართა შორის პატივისა და ზიარების წესრიგი."),
"diskos": ("დისკოსი", "ფეხიანი ლანგარი, რომელზეც იდება კრავი და სახსენებელი ნაწილაკები."),
"dispassion": ("უვნებობა (ინგლ. dispassion)", "სიტყვა apatheia-ს ინგლისური გადმოცემა; იხ. შესაბამისი სტატია."),
"divine-liturgy": ("საღვთო ლიტურგია", "ეკლესიის ევქარისტიული მსახურება, რომელზეც პური და ღვინო შეიწირება და ხდება ქრისტეს ხორცი და სისხლი. უმეტესად აღესრულება წმიდა იოანე ოქროპირის წესით."),
"dormition-fast": ("მიძინების მარხვა", "მარხვა 1-დან 14 აგვისტომდე, ღვთისმშობლის მიძინების წინ."),
"economia": ("იკონომია", "მწყემსური განსჯა, რომლითაც კანონის მკაცრი გამოყენება შერბილდება სულთა ცხონებისთვის; აკრივიის შესატყვისი."),
"ecumenical-council": ("მსოფლიო კრება", "კრება, რომლის განჩინებანიც მიიღო მთელმა ეკლესიამ. მართლმადიდებელი ეკლესია ცნობს შვიდს, ნიკეის 325 წლიდან მეორე ნიკეის 787 წლამდე."),
"elder": ("ბერი (გერონდა)", "განსჯის მქონე მონაზონი, რომელსაც სხვები უმხელენ თავიანთ ზრახვებს და მისგან იღებენ ხელმძღვანელობას."),
"epigonation": ("ეპიგონატიონი (ბარძაყისა)", "მაგარი რომბისებრი ქსოვილი, ჩამოკიდებული მარჯვენა მუხლთან, მიცემული ჯილდოდ; აღნიშნავს სულის მახვილს."),
"epiklesis": ("ეპიკლეზა", "სულიწმიდის მოხმობა ძღვენზე და შეკრებილთა ზედა, რომლის დროსაც მართლმადიდებელი ეკლესია გულისხმობს კურთხევის აღსრულებას."),
"epimanikia": ("სამაჯურები (ეპიმანიკია)", "სამკლავეები, რომელთაც ატარებენ სასულიერო პირები; ისინი კრავენ სახელოებს და აღნიშნავენ ქრისტეს კვართს."),
"epitaphios": ("საფლავის საბურველი (ეპიტაფიოსი)", "ნაქარგი ქსოვილი ქრისტეს საფლავად დადებულის ხატებით, რომელიც დიდ პარასკევს გამოაქვთ ლიტანიობით."),
"epitimia": ("ეპიტიმია", "წესი, მიცემული აღსარებაზე წამლად და არა სასჯელად: მუხლმოდრეკა, მოწყალება ან ზიარებისგან დროებით თავშეკავება."),
"epitrachelion": ("ეპიტრაქილი", "მღვდლის ეპიტრაქილი, ტარებული კისერზე. მის გარეშე არც ერთი სამღვდელო მსახურება არ სრულდება."),
"essence-energies": ("არსება და ენერგიები", "წმიდა გრიგოლ პალამას მიერ ჩამოყალიბებული განსხვავება ღვთის შეუცნობელ არსებასა და მის უქმნელ ენერგიებს შორის, რომელთა მეშვეობითაც იგი ჭეშმარიტად ეზიარება."),
"euchologion": ("კურთხევანი (ევქოლოგიონი)", "მღვდლის საღვთისმსახურო წიგნი, რომელიც შეიცავს ჟამისწირვის ლოცვებს, საიდუმლოებსა და საჭიროებისამებრ მსახურებებს."),
"fast-free": ("უმარხვო შვიდეული", "შვიდეული, რომელშიც უქმდება ოთხშაბათისა და პარასკევის მარხვა, როგორც ბრწყინვალე შვიდეული და სულთმოფენობის შემდგომი შვიდეული."),
"forefeast": ("წინადღესასწაული და დღესასწაულის გაგრძელება", "მზადების დღეები დიდი დღესასწაულის წინ და გაგრძელების დღეები მის შემდეგ."),
"forgiveness-vespers": ("შენდობის მწუხრი", "მწუხრი დიდი მარხვის დაწყების წინა საღამოს, რომელზეც მორწმუნენი ერთმანეთს შენდობას სთხოვენ."),
"glorification": ("წმიდანად შერაცხვა", "ეკლესიის აღიარება იმისა, რომ ადამიანი წმიდანთა შორისაა, რითაც განმტკიცდება თაყვანისცემა, უკვე აღმოცენებული მორწმუნეთა შორის."),
"theophany-water": ("წყალკურთხევა დიდი", "წყლის კურთხევა ნათლისღებაზე; ინახება მთელი წლის განმავლობაში და საჭიროებისას ისმევა."),
"doxology": ("დიდი დიდებისმეტყველება", "დიდება მაღალთა შინა ღმერთსა, გალობილი ცისკრის დასასრულს კვირაობით და დღესასწაულებზე."),
"great-entrance": ("დიდი შესვლა", "მსვლელობა, რომელიც გადმოაქვს მომზადებულ ძღვენს პროსკომიდიიდან საკურთხევლის ტრაპეზზე, ქერუბიმთა საგალობლის დროს."),
"great-feasts": ("დიდი დღესასწაულები", "წლის თორმეტი დიდი დღესასწაული აღდგომასთან ერთად, რომელიც მათზე მაღლა დგას როგორც დღესასწაულთა დღესასწაული."),
"great-lent": ("დიდი მარხვა", "ორმოცდღიანი მარხვა ვნების შვიდეულისა და აღდგომის წინ, რომელიც სუფთა ორშაბათს იწყება."),
"great-schema": ("დიდი სქემა", "სამონაზვნო აღკვეცის უმაღლესი ხარისხი, ანალავითა და გაძლიერებული ლოცვისა და განდგომის წესით."),
"hesychasm": ("ისიხაზმი", "შინაგანი სიჩუმისა და განუწყვეტელი ლოცვის ტრადიცია, დაცული წმიდა გრიგოლ პალამას მიერ და დამტკიცებული მეთოთხმეტე საუკუნის კრებათა მიერ."),
"hierodeacon": ("იერდიაკონი", "მონაზონი, ხელდასხმული დიაკვნად."),
"hieromonk": ("მღვდელმონაზონი", "მონაზონი, ხელდასხმული მღვდლად."),
"myron": ("წმიდა მირონი", "სურნელოვანი ზეთი, კურთხეული პატრიარქის ან სინოდის მიერ და ხმარებული მირონცხებაზე."),
"altar-table": ("საკურთხევლის ტრაპეზი", "ტრაპეზი საკურთხევლის შუაგულში, რომელზეც შეიწირება ჟამისწირვა; იგი შეიცავს ნაწილებს."),
"unction": ("ზეთისკურთხევა", "სნეულთა ცხება კურთხეული ზეთით სულისა და ხორცის განკურნებისთვის, აღსრულებული რამდენიმე მღვდლის მიერ, სადაც ეს შესაძლებელია."),
"holy-week": ("ვნების შვიდეული", "შვიდეული ბზობიდან დიდ შაბათამდე, დიდი მარხვის შემდეგ და აღდგომის წინ."),
"horologion": ("ჟამნი", "ჟამთა წიგნი, რომელიც შეიცავს მსახურებათა დღიური წრის უცვლელ ნაწილებს."),
"hypostasis": ("იპოსტასი", "პირი, განსხვავებით ბუნებისა და არსებისაგან. სამება არის სამი იპოსტასი ერთ არსებაში; ქრისტე არის ერთი იპოსტასი ორ ბუნებაში."),
"iconography": ("ხატი", "ქრისტეს, ღვთისმშობლის ან წმინდანთა დაწერილი ხატება, თაყვანცემული, ვინაიდან პატივი პირმშოსახეზე გადადის. დაცული იქნა მეშვიდე მსოფლიო კრებაზე."),
"iconostasis": ("კანკელი (იკონოსტასი)", "ხატებიანი ტიხარი ტაძარსა და საკურთხეველს შორის, სამეუფო კარით შუაში და ხატთა დადგენილი წესრიგით."),
"incarnation": ("განკაცება", "საუკუნო სიტყვის მიერ ადამიანური ბუნების მიღება, ჭეშმარიტი ღმერთი და ჭეშმარიტი კაცი ერთ პირში."),
"incense": ("საკმეველი", "იწვება მსახურებებზე, აღმნიშვნელი ლოცვისა, რომელიც ღვთის წინაშე აღვლენილია."),
"incorrupt": ("უხრწნელობა", "წმინდანის სხეულის დაცვა ხრწნისგან, მიღებული სიწმინდის ნიშნად, თუმცა არ არის აუცილებელი წმიდანად შერაცხვისთვის."),
"indiction": ("ინდიქტიონი", "საეკლესიო წლის დასაწყისი 1 სექტემბერს."),
"irmos": ("ირმოსი", "კანონის თითოეული გალობის პირველი ტროპარი, რომელიც განსაზღვრავს მის კილოსა და საზომს და აკავშირებს მას ბიბლიურ გალობასთან."),
"jesus-prayer": ("იესოს ლოცვა", "უფალო იესო ქრისტე, ძეო ღვთისაო, შემიწყალე მე ცოდვილი, გამეორებული როგორც განუწყვეტელი ლოცვის საფუძველი."),
"julian-calendar": ("იულიანური და შესწორებული იულიანური კალენდარი", "ძველი იულიანური, რომელსაც რამდენიმე ეკლესია მთელი წლის განმავლობაში იცავს, და შესწორებული იულიანური, რომელიც უძრავ დღესასწაულებში გრიგორიანულს მისდევს იულიანური პასქალიის შენარჩუნებით."),
"katavasia": ("კატავასია", "ირმოსი, გამეორებული გალობის ბოლოს; ასე ეწოდა იმიტომ, რომ გუნდები ჩამოდიოდნენ თავიანთი ადგილებიდან მის ერთად საგალობლად."),
"kathisma": ("კათისმა", "ფსალმუნის ოცი ნაწილიდან ერთი; აგრეთვე საჯდომი საგალობელი, რომელიც მის შემდეგ იგალობება და რომლის დროსაც ჯდომა ნებადართულია."),
"kenosis": ("კენოზისი", "ძის თავდადაცარიელება განკაცებაში, რომელზეც საუბრობს ფილიპელთა მიმართ ეპისტოლის მე-2 თავი."),
"klobuk": ("კუნკული (კლობუკი)", "სამონაზვნო თავსაბურავი: ცილინდრული ქუდი საბურველით."),
"koliva": ("კოლიო", "მოხარშული ხორბალი თაფლითა და ხილით, კურთხეული სახსენებელზე, უფლის სიტყვათა მიხედვით, რომ მარცვალი უნდა მოკვდეს ნაყოფის გამოსატანად."),
"kontakion": ("კონდაკი", "მეორე მოკლე საგალობელი, რომელიც შეაჯამებს დღესასწაულს ან წმინდანს. თავდაპირველად ეს იყო ვრცელი პოეტური ქადაგება მრავალ სტროფად, რომლის შემორჩენილი კონდაკი პირველია."),
"lance": ("ლახვარი", "პატარა შუბისებრი დანა, რომლითაც პროსკომიდიაზე იჭრება კრავი და ნაწილაკები; მოგვაგონებს ლახვარს, რომელმაც ქრისტეს გვერდი განგმირა."),
"leavetaking": ("დღესასწაულის დასრულება (აპოდოსისი)", "დღესასწაულის შემდგომი დღეების უკანასკნელი დღე, დაცული თვით დღესასწაულის საგალობელთა დიდი ნაწილით."),
"little-entrance": ("მცირე შესვლა", "მსვლელობა სახარებით ჟამისწირვის დასაწყისთან ახლოს."),
"liturgy-of-basil": ("წმიდა ბასილი დიდის ლიტურგია", "საღვთო ლიტურგიის უფრო ვრცელი სახე თავისი ანაფორით, აღსრულებული წელიწადში ათჯერ: დიდი მარხვის კვირებში ბზობის გარდა, დიდ ხუთშაბათსა და დიდ შაბათს, შობისა და ნათლისღების წინა დღეებში და წმიდა ბასილის დღესასწაულზე 1 იანვარს."),
"presanctified": ("პირველადკურთხეულ ძღვენთა ლიტურგია", "მწუხრის მსახურება ზიარებით იმ ძღვენისგან, რომელიც წინა კვირის ჟამისწირვაზე იქნა კურთხეული; აღესრულება დიდი მარხვის სამუშაო დღეებში, როცა სრული ჟამისწირვა არ სრულდება."),
"litya": ("ლიტია", "მსვლელობა და ვედრება ღამისთევაზე, რომლის დროსაც იკურთხება პური, ხორბალი, ღვინო და ზეთი."),
"logismoi": ("ზრახვები (ლოღიზმები)", "ზრახვები ან შთაგონებანი, რომელნიც გონებას ეტევიან და უნდა გამოირჩეს და უარიყოს, ვიდრე თანხმობად იქცეოდნენ."),
"mandyas": ("მანტია", "სრული მანტია, რომელსაც ეპისკოპოსი ატარებს მსვლელობაში, ხოლო უფრო მარტივი სახით დიდი სქემის მონაზვნები."),
"menaion": ("თვენი (მინეა)", "თორმეტი ტომი უძრავ დღესასწაულთა საგალობლებისა, თითო წლის თითოეული თვისთვის."),
"menologion": ("მინოლოგიონი", "წმინდანთა ცხოვრებათა კრებული, დალაგებული თვის დღეთა მიხედვით."),
"metanoia": ("მეტანოია (სინანული)", "სიტყვასიტყვით გონების შეცვლა, მთელი ადამიანის მიქცევა ღვთისკენ. იმავე სიტყვით იწოდება მუხლმოდრეკაც."),
"metropolitan": ("მიტროპოლიტი", "მთავარი ქალაქის ეპისკოპოსი, თავისი მხარის ეპისკოპოსებზე მაღლა მდგომი. ხმარება განსხვავდება ბერძნულ და სლავურ ეკლესიებში."),
"moleben": ("სამადლობელი პარაკლისი (მოლებენი)", "სავედრებელი მსახურება ქრისტესადმი, ღვთისმშობლისა თუ წმინდანისადმი, უძრავი წრის გარეთ, გარკვეული საჭიროებისთვის ან მადლობისთვის."),
"monk": ("მონაზონი", "სამონაზვნო ცხოვრებისთვის აღკვეცილი, მორჩილების, სიწმინდისა და უპოვარების აღთქმებით."),
"mystery": ("საიდუმლო", "ეკლესიის მოქმედება, რომელშიც მადლი მიეცემა ხილული საშუალებებით. მართლმადიდებელ ეკლესიას მათი რიცხვი დოგმატურად არასოდეს განუსაზღვრავს, თუმცა ჩვეულებრივ შვიდს ასახელებენ."),
"nabedrennik": ("ნაბედრენიკი", "ოთხკუთხა ქსოვილი, ტარებული თეძოსთან; სლავურ ეკლესიათა ჯილდო, რომელსაც ბერძნული შესატყვისი არ აქვს."),
"narthex": ("სტოა (ნართექსი)", "ტაძრის შესასვლელი დარბაზი, სადაც ოდესღაც იდგნენ მოქათალენი და მონანულნი და სადაც იწყება რამდენიმე მსახურება."),
"nativity-fast": ("შობის მარხვა", "ორმოცდღიანი მარხვა 15 ნოემბრიდან ქრისტეს შობის წინ."),
"nave": ("ტაძრის შუაგული (ნაოსი)", "ტაძრის სხეული, სადაც დგანან მორწმუნენი."),
"nepsis": ("სიფხიზლე (ნეფსისი)", "ფხიზელი ყურადღება ზრახვებისადმი მათი გაჩენისთანავე, რათა შეხვდნენ მათ ვიდრე ფესვს გაიდგამდნენ."),
"novice": ("გამოსაცდელი (მორჩილი)", "ის, ვინც მონასტერში ცხოვრობს გამოსაცდელად აღკვეცამდე."),
"obedience": ("მორჩილება", "საკუთარი ნების მოკვეთა ბერის ან წესის წინაშე; აგრეთვე მონაზონისთვის დაკისრებული განსაზღვრული საქმე."),
"octoechos": ("პარაკლიტონი (ოქტოიხოსი)", "რვა ხმის წიგნი, რომელიც აწესრიგებს ჩვეულებრივ შვიდეულთა აღდგომის საგალობლებს რვაშვიდეულიან წრეში."),
"oikos": ("იკოსი", "სტროფი, რომელიც კონდაკს მოსდევს და მის თემას ავრცობს."),
"omophorion": ("ომოფორი", "განიერი ლენტი, ტარებული ეპისკოპოსის მხრებზე, აღმნიშვნელი დაკარგული ცხვრისა, რომელსაც კეთილი მწყემსი ატარებს. იგი აღნიშნავს მის ხარისხს."),
"orarion": ("ორარი", "გრძელი ვიწრო ლენტი დიაკვნის მარცხენა მხარზე, ამაღლებული კვერექსებზე."),
"orthros": ("ცისკარი", "დილის მსახურება, ყველაზე ვრცელი დღიურ წრეში, რომელიც შეიცავს ექვსფსალმუნს, კანონს და უმეტეს წესებში დიდ დიდებისმეტყველებას."),
"panagia": ("პანაგია", "ღვთისმშობლის მედალიონი-ხატი, ტარებული ეპისკოპოსის მკერდზე."),
"panikhida": ("პანაშვიდი", "გარდაცვლილთა სახსენებელი მსახურება, აღსრულებული მესამე, მეცხრე და მეორმოცე დღეს, წლისთავებზე და მიცვალებულთა შაბათებში."),
"paraklesis": ("პარაკლისი", "სავედრებელი კანონი ღვთისმშობლისადმი. მცირე იგალობება მიძინების მარხვის მანძილზე; დიდი ეკუთვნის განსაკუთრებული ჭირის ჟამს."),
"pascha": ("აღდგომა (პასექი)", "ქრისტეს აღდგომა, დღესასწაულთა დღესასწაული, საიდანაც ითვლება მოძრავი წრე."),
"paschalion": ("პასქალია", "აღდგომის თარიღის გამოთვლა და ცხრილი, რომლითაც იგი მოიძებნება."),
"passions": ("ვნებანი", "სულის უწესრიგო მოძრაობანი: არა თავად ბუნებრივი სურვილები, არამედ მათი გახრწნა მონობად."),
"patriarch": ("პატრიარქი", "საპატრიარქო ხარისხის ავტოკეფალური ეკლესიის წინამძღვარი."),
"pentecostarion": ("ზატიკი (პენტიკოსტარიონი)", "წიგნი და პერიოდი აღდგომიდან ყოველთა წმიდათა კვირამდე."),
"penthos": ("გლოვა (პენთოსი)", "ცოდვისთვის გლოვა, ღვთის მიერი მწუხარება, რომელიც სინანულს შობს, ხშირად ცრემლებთან ერთად."),
"phelonion": ("ფელონი", "მღვდლის განიერი უსახელო გარეთა შესამოსელი ჟამისწირვაზე."),
"philokalia": ("ფილოკალია (კეთილმოსიყვარულება)", "ასკეტურ და ჭვრეტით ტექსტთა კრებული მეოთხე საუკუნიდან მეთხუთმეტემდე, შედგენილი წმიდა ნიკოდიმოსისა და კორინთოს წმიდა მაკარის მიერ, გამოცემული 1782 წელს."),
"phronema": ("ფრონემა (საეკლესიო გონება)", "ეკლესიის გონება ან აზროვნების წესი, რომელიც ყალიბდება მასში ცხოვრებით და არა მხოლოდ სწავლით."),
"phyletism": ("ფილეტიზმი", "ეკლესიის აღრევა ერთან, დაგმობილი ერესად კონსტანტინოპოლის კრების მიერ 1872 წელს."),
"polyeleos": ("პოლიელეოსი", "134-ე და 135-ე ფსალმუნები, გალობილი სადღესასწაულო ცისკარზე, ასე წოდებული მათი მისამღერიდან, რამეთუ უკუნისამდე არს წყალობაი მისი."),
"departed-prayers": ("ლოცვა გარდაცვლილთათვის", "ეკლესიის ჩვეულება, ილოცოს მიცვალებულთათვის, გამოხატული პანაშვიდში, მიცვალებულთა შაბათებში და პროსკომიდიის მოხსენიებებში."),
"prayer-of-heart": ("გულის ლოცვა", "იესოს ლოცვა, გონებიდან გულში ჩამოსული და განუწყვეტელი გამხდარი."),
"prayer-rope": ("კვანძოვანი კრიალოსანი", "კვანძებიანი შალის თოკი იესოს ლოცვის დასათვლელად, ჩვეულებრივ ოცდაცამეტი, ორმოცდაათი ან ასი კვანძით."),
"priest": ("მღვდელი (პრესვიტერი)", "მეორე ხარისხი, ეპისკოპოსის მიერ ხელდასხმული სამრევლოში ჟამისწირვისა და საიდუმლოთა აღსასრულებლად."),
"prokeimenon": ("წარდგომა (პროკიმენი)", "მუხლი, ჩვეულებრივ ფსალმუნიდან, გალობილი საწერილო საკითხავის წინ."),
"prosoche": ("ყურადღება (პროსოხი)", "ყურადღება; გონების დაცვა ლოცვაში."),
"prosphora": ("პროსფორა", "საფუარიანი პური, შეწირული ჟამისწირვისთვის, დაბეჭდილი ბეჭდით, საიდანაც იჭრება კრავი."),
"prostration": ("მიწამდე თაყვანისცემა", "მიწამდე დახრა, აღსრულებული სინანულსა და თაყვანისცემაში. მიწამდე თაყვანისცემა არ აღესრულება კვირაობით და აღდგომის პერიოდში."),
"prothesis": ("პროსკომიდია", "პურისა და ღვინის მომზადება ჟამისწირვის წინ, შესაწირავ ტრაპეზზე, რომლის დროსაც იჭრება ნაწილაკები ცოცხალთა და გარდაცვლილთათვის."),
"psalter": ("ფსალმუნი", "ას ორმოცდაათი ფსალმუნი, დაყოფილი ოც კათისმად მსახურებებზე წასაკითხად, ცხრა ბიბლიურ გალობასთან ერთად."),
"rassophore": ("რასოფორი", "სამონაზვნო აღკვეცის პირველი ხარისხი, კვართის მტვირთველი, სრული აღთქმების გარეშე."),
"reader": ("მკითხველი", "მცირე ხარისხი, დადგენილი სამოციქულოსა და დანიშნულ ტექსტთა საკითხავად."),
"relics": ("ნაწილები", "წმინდანთა სხეულებრივი ნეშტი, პატივცემული იმის გამო, რომ სხეული სულიწმიდის ტაძარია. ნაწილები დაბეჭდილია ანტიმინსსა და საკურთხევლის ტრაპეზში."),
"royal-doors": ("სამეუფო კარი", "კანკელის შუა კარი, რომლითაც მხოლოდ სასულიერო პირები გადიან და რომლითაც შემოაქვთ ძღვენი."),
"sakkos": ("სააკოსი", "ეპისკოპოსის გარეთა შესამოსელი, რომელმაც ფელონი შეცვალა მღვდელმთავრებისთვის."),
"salutations": ("სამხიარულონი (ხარებანი)", "დიდი მარხვის პარასკევის საღამოს მსახურებანი, რომლებზეც ღვთისმშობლის აკათისტო ნაწილ-ნაწილ იგალობება."),
"sanctuary": ("საკურთხეველი", "სივრცე კანკელს მიღმა, რომელიც შეიცავს საკურთხევლის ტრაპეზს, შესაწირავ ტრაპეზსა და მაღალ ადგილს."),
"solea": ("სოლეა", "ამაღლებული ბილიკი კანკელის წინ, საიდანაც ეზიარებიან მორწმუნენი."),
"soul-saturday": ("მიცვალებულთა შაბათი", "შაბათები, დაწესებული ყოველთა გარდაცვლილთა მოსახსენებლად."),
"spiritual-father": ("სულიერი მამა", "მღვდელი ან ბერი, რომელიც აღსარებას ისმენს და ხელმძღვანელობს ადამიანის ცხოვრებას ქრისტეში."),
"stavrophore": ("სტავროფორი (მცირე სქემა)", "სამონაზვნო აღკვეცის მეორე ხარისხი, ჯვრის მტვირთველი, რომელზეც სრული აღთქმები მიიღება."),
"stavrotheotokion": ("ჯვართა ღვთისმშობლისა", "ღვთისმშობლისა ჯვართან მდგომის შესახებ, გამოყენებული ოთხშაბათსა და პარასკევს."),
"sticharion": ("სტიქარი", "გრძელი კვართი, ტარებული სასულიერო პირთა ყველა ხარისხის მიერ, აგრეთვე მკითხველთა და მსახურთა მიერ."),
"sticheron": ("სტიქარონი", "საგალობელი, გალობილი ფსალმუნის მუხლებს შორის, უპირატესად მწუხრსა და ცისკარზე."),
"subdeacon": ("იპოდიაკონი", "მცირე ხარისხი, რომელიც ემსახურება ეპისკოპოსს და უვლის ჭურჭელს."),
"synaxarion": ("სვინაქსარი", "თხრობა დღისთვის დანიშნულ წმინდანთა და დღესასწაულთა შესახებ, წაკითხული ცისკარზე; აგრეთვე წიგნი, რომელიც მათ კრებს."),
"tabernacle": ("კიდობანი", "ჭურჭელი საკურთხევლის ტრაპეზზე, რომელშიც ინახება პირველადკურთხეული ძღვენი სნეულთათვის და პირველადკურთხეულთა ლიტურგიისთვის."),
"hours": ("ჟამნი (საათები)", "დღის ოთხი მოკლე მსახურება: პირველი, მესამე, მეექვსე და მეცხრე, აღრიცხული მზის ამოსვლიდან, თითოეული თავისი ფსალმუნებითა და თემით."),
"lamb": ("კრავი", "ოთხკუთხა ნაწილი, ამოჭრილი პირველი პროსფორიდან, რომელიც იკურთხება და ხდება ქრისტეს ხორცი."),
"rudder": ("საჭე (პიდალიონი)", "ეკლესიის კანონთა მთავარი ბერძნული კრებული განმარტებით, შედგენილი წმიდა ნიკოდიმოს მთაწმიდელისა და წმიდა აღაპიოსის მიერ, გამოცემული 1800 წელს."),
"theosis": ("გაღმერთება (თეოსისი)", "ადამიანური პიროვნების ზიარება ღვთაებრივ ცხოვრებასთან მადლით, მიზანი, რომლისთვისაც შეიქმნა კაცი. მადლით და არა ბუნებით."),
"theotokion": ("ღვთისმშობლისა", "საგალობელი ღვთისმშობლისადმი, დასმული საგალობელთა ჯგუფის ბოლოს."),
"theotokos": ("ღვთისმშობელი", "ღვთის მშობელი, ქალწული მარიამის წოდება, დამტკიცებული ეფესოში 431 წელს. იგი იცავს იმ ჭეშმარიტებას, რომ მისგან შობილი არის ღმერთი."),
"tone": ("ხმა (იხოსი)", "რვა მუსიკალური კილოდან ერთი, რომლითაც იგალობება საგალობლები, შვიდეულიდან შვიდეულამდე ცვალებადი პარაკლიტონის მიხედვით."),
"triodion": ("მარხვანი (ტრიოდიონი)", "წიგნი და პერიოდი დიდი მარხვის წინა და მისი შვიდეულებისა, დიდ შაბათამდე. ასე ეწოდა თავისი სამგალობიანი კანონების გამო."),
"trisagion": ("სამწმიდაო", "წმიდაო ღმერთო, წმიდაო ძლიერო, წმიდაო უკვდავო, შეგვიწყალენ ჩვენ, გალობილი სამგზის; აგრეთვე იმ მოკლე ლოცვათა კრებულის სახელი, რომლითაც იწყება მსახურებათა უმეტესობა."),
"troparion": ("ტროპარი", "დღესასწაულის ან წმინდანის მთავარი მოკლე საგალობელი, რომელიც მის თემას გადმოსცემს. იწოდება აგრეთვე გამოსატანად, როცა იგალობება გამოსვლისას."),
"typikon": ("ტიპიკონი", "წესთა წიგნი, რომელიც მიუთითებს, როგორ ინახება მსახურებანი და მარხვები და როგორ ერწყმის ერთმანეთს წრეები დამთხვევისას."),
"veneration": ("პატივისცემა და თაყვანისცემა", "მეორე ნიკეის კრებაზე დამტკიცებული განსხვავება: სამსახურებრივი თაყვანისცემა ეკუთვნის მხოლოდ ღმერთს, ხოლო პატივისცემა მიეგება ხატებს, ნაწილებსა და წმინდანებს."),
"vespers": ("მწუხრი", "საღამოს მსახურება, რომლითაც იწყება საღვთისმსახურო დღე. იხსნება 103-ე ფსალმუნით და კანდელთა აღნთებით."),
"xerophagy": ("მშრალჭამია (ქსეროფაგია)", "ჩვეულებრივი მარხვის უმკაცრესი ხარისხი, ზეთისა და ღვინის გარეშე, დაცული დიდი მარხვის სამუშაო დღეებში."),
"zeon": ("ზეონი (თბილი)", "ცხელი წყალი, ჩასხმული ბარძიმში ზიარების წინ, აღმნიშვნელი სულიწმიდის სითბოსი და იმისა, რომ მიღებული ხორცი ცოცხალია."),
"zone": ("სარტყელი", "სარტყელი, რომელსაც მღვდელი ან ეპისკოპოსი ატარებს სტიქარსა და ეპიტრაქილზე."),
}
